                <div><strong>Name:</strong> {{ doc.billing_address or "N/A" }}</div>
                <div><strong>Address:</strong> {{ billing_address.get('address_line1', 'N/A') }}, {{ billing_address.get('city', 'N/A') }}, {{ billing_address.get('country', 'N/A') }}</div>
