            <TD colspan="2" rowspan="2" style="border: 1px solid black; text-align:center; padding: 5px;"><b>Taxable Value</b></TD>
            <TD colspan="2" style="border: 1px solid black; text-align:center; padding: 5px;"><b>Central Tax</b></TD>
            <TD colspan="2" style="border: 1px solid black; text-align:center; padding: 5px;"><b>State Tax</b></TD>
        </TR>
        <TR style="border: 1px solid black;">
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">Rate</TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">Amount</TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">Rate</TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">Amount</TD>
        </TR>
       {% set gst_rates = {} %}

{% for item in doc.items %}
    {% set tax_template = frappe.get_doc("Item Tax Template", item.item_tax_template) if item.item_tax_template else None %}
    {% set gst_rate = (tax_template.gst_rate|int|string + "%") if tax_template else "N/A" %}
    {% set taxable_amount = item.net_amount|float %}

    {% if gst_rates.get(gst_rate) %}
        {% set new_amount = gst_rates[gst_rate] + taxable_amount %}
        {% set _ = gst_rates.update({gst_rate: new_amount}) %}
    {% else %}
        {% set _ = gst_rates.update({gst_rate: taxable_amount}) %}
    {% endif %}
{% endfor %}

<!-- GST Breakdown Table -->
{% for gst_rate, taxable_amount in gst_rates.items() %}
<tr style="border: 1px solid black;">
    <td colspan="2" style="border: 1px solid black; text-align:left; padding: 5px;">{{ gst_rate }}</td>
    <td colspan="2" style="border: 1px solid black; text-align:right; padding: 5px;">{{ frappe.utils.fmt_money(taxable_amount, currency='') }}</td>
