    <td style="border: 1px solid black; text-align:right; padding: 5px;">{{ frappe.utils.fmt_money((taxable_amount * (gst_rate[:-1]|float) / 2) / 100, currency='') }}</td>
    <td style="border: 1px solid black; text-align:right; padding: 5px;">{{ (gst_rate[:-1]|float) / 2 }}%</td>
    <td style="border: 1px solid black; text-align:right; padding: 5px;">{{ frappe.utils.fmt_money((taxable_amount * (gst_rate[:-1]|float) / 2) / 100, currency='') }}</td>
</tr>
